import {
  WorkflowEntrypoint,
  type WorkflowEvent,
  type WorkflowStep,
} from "cloudflare:workers";

type Env = {
  IMAGE_PROCESSING: Workflow;
  BUCKET?: R2Bucket;
  AI?: Ai;
};

type Params = {
  imageKeys: string[];
  autoApproveThreshold: number;
};

type AnalysisResult = {
  description: string;
  confidence: number;
};

type ProcessedImage = {
  key: string;
  description: string;
  confidence: number;
  approval: "auto" | "human";
};

export class ImageProcessingWorkflow extends WorkflowEntrypoint<Env, Params> {
  async run(event: WorkflowEvent<Params>, step: WorkflowStep) {
    const { imageKeys, autoApproveThreshold } = event.payload;
    const processed: ProcessedImage[] = [];

    for (const imageKey of imageKeys) {
      const imageData = await step.do(`fetch image: ${imageKey}`, async () => {
        const object = await this.env.BUCKET!.get(imageKey);
        return await object!.arrayBuffer();
      });

      const analysis = await step.do(
        `analyze: ${imageKey}`,
        async (): Promise<AnalysisResult> => {
          const imageArray = Array.from(new Uint8Array(imageData));
          const result = await this.env.AI!.run(
            "@cf/llava-hf/llava-1.5-7b-hf",
            {
              image: imageArray,
              prompt: "Describe this image in one sentence",
              max_tokens: 50,
            },
          );
          const description = (result as { description: string }).description;
          return {
            description,
            confidence: Math.min(description.length / 60, 1),
          };
        },
      );

      if (analysis.confidence >= autoApproveThreshold) {
        await step.do(`auto-publish: ${imageKey}`, async () => {
          await this.env.BUCKET!.put(`public/${imageKey}`, imageData);
        });
        processed.push({
          key: imageKey,
          description: analysis.description,
          confidence: analysis.confidence,
          approval: "auto",
        });
      } else {
        await step.waitForEvent(`await approval: ${imageKey}`, {
          type: `approved:${imageKey}`,
          timeout: "24 hours",
        });
        await step.do(`publish after approval: ${imageKey}`, async () => {
          await this.env.BUCKET!.put(`public/${imageKey}`, imageData);
        });
        processed.push({
          key: imageKey,
          description: analysis.description,
          confidence: analysis.confidence,
          approval: "human",
        });
      }
    }

    return { processed };
  }
}

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);

    if (url.pathname === "/start") {
      const keys = url.searchParams.get("imageKeys") ?? "sample-1.jpg,sample-2.jpg";
      const threshold = Number(url.searchParams.get("threshold") ?? "0.7");
      const instance = await env.IMAGE_PROCESSING.create({
        params: {
          imageKeys: keys.split(",").map((k) => k.trim()).filter(Boolean),
          autoApproveThreshold: threshold,
        },
      });
      return Response.json({ id: instance.id, status: await instance.status() });
    }

    if (url.pathname === "/status") {
      const id = url.searchParams.get("id");
      if (!id) return new Response("missing id", { status: 400 });
      const instance = await env.IMAGE_PROCESSING.get(id);
      return Response.json(await instance.status());
    }

    if (url.pathname === "/approve") {
      const id = url.searchParams.get("id");
      const imageKey = url.searchParams.get("imageKey");
      if (!id || !imageKey) {
        return new Response("missing id or imageKey", { status: 400 });
      }
      const instance = await env.IMAGE_PROCESSING.get(id);
      await instance.sendEvent({ type: `approved:${imageKey}`, payload: {} });
      return Response.json({ ok: true });
    }

    return new Response(
      "ImageProcessingWorkflow demo (batch + conditional approval)\n" +
        "GET /start?imageKeys=a.jpg,b.jpg&threshold=0.7 to trigger\n" +
        "GET /status?id=<id> to inspect an instance\n" +
        "GET /approve?id=<id>&imageKey=<key> to release a human-approval wait\n",
      { headers: { "content-type": "text/plain; charset=utf-8" } },
    );
  },
} satisfies ExportedHandler<Env>;

